<script setup>
import { computed, ref, onMounted } from 'vue'
import { loadJournal, saveJournal, uid, today } from '../../lib/store'
import { cloudAvailable, cloudToken, login, pullJournal, pushJournal, uploadMedia, setCloudToken, socialFeed, sharePost, likeSocial, commentSocial } from '../../lib/cloud'

const journal = ref(loadJournal())
const activeTab = ref('timeline')
const selectedPetId = ref('all')
const selectedPost = ref(null)
const socialMode = ref(false)
const socialPosts = ref([])
const sheet = ref('')
const busy = ref(false)
const error = ref('')
const postDraft = ref({ date: today(), text: '', media: [], petIds: [], public: false })
const petDraft = ref({})
const eventDraft = ref({ type: 'vaccine', title: '', date: today(), note: '' })
const authDraft = ref({ email: '', password: '', mode: 'login' })
const commentFor = ref('')
const commentText = ref('')
const pets = computed(() => journal.value.pets || [])
const pet = computed(() => pets.value.find(p => p.id === selectedPetId.value) || pets.value[0] || {})
const petName = post => (post.petIds || []).map(id => pets.value.find(p => p.id === id)?.name).filter(Boolean).join('、') || '我的宠物'
const posts = computed(() => [...journal.value.moments].filter(p => selectedPetId.value === 'all' || (p.petIds || []).includes(selectedPetId.value)).sort((a, b) => b.date.localeCompare(a.date) || b.createdAt.localeCompare(a.createdAt)))
const events = computed(() => [...journal.value.events].filter(e => selectedPetId.value === 'all' || e.petId === selectedPetId.value).sort((a, b) => b.date.localeCompare(a.date)))
const latestDeworm = computed(() => events.value.find(e => e.type === 'deworm'))
const nextVaccine = computed(() => [...journal.value.events].filter(e => e.type === 'vaccine' && e.date >= today()).sort((a,b) => a.date.localeCompare(b.date))[0])
const age = computed(() => { if (!pet.value.birthday) return ''; const birth = new Date(pet.value.birthday); const now = new Date(); let years = now.getFullYear() - birth.getFullYear(); if (now.getMonth() < birth.getMonth() || (now.getMonth() === birth.getMonth() && now.getDate() < birth.getDate())) years--; return years < 1 ? '未满 1 岁' : `${years} 岁` })
const countPhotos = computed(() => journal.value.moments.reduce((n, p) => n + (p.media || []).filter(m => m.type === 'image').length, 0))
const formatDate = date => { if (!date) return '未填写'; const [y,m,d] = date.split('-'); return `${y}年${Number(m)}月${Number(d)}日` }
const monthDay = date => { const [,m,d] = date.split('-'); return { month: `${Number(m)}月`, day: d } }
const notify = msg => uni.showToast({ title: msg, icon: 'none' })
function commit() { saveJournal(journal.value); if (cloudAvailable && cloudToken()) pushJournal(journal.value).catch(() => notify('已保存在本机，云端稍后同步')) }
function openPost() { postDraft.value = { date: today(), text: '', media: [], public: false, petIds: [selectedPetId.value === 'all' ? pets.value[0]?.id : selectedPetId.value].filter(Boolean) }; sheet.value = 'post'; error.value = '' }
function openPet(target = pet.value) { petDraft.value = { ...target }; sheet.value = 'pet'; error.value = '' }
function openEvent(type = 'vaccine') { eventDraft.value = { petId: pet.value.id, type, title: type === 'vaccine' ? '疫苗接种' : '驱虫', date: today(), note: '' }; sheet.value = 'event'; error.value = '' }
function closeSheet() { if (!busy.value) { sheet.value = ''; error.value = '' } }
function chooseMedia(type) {
  const isVideo = type === 'video'
  const onFail = err => { if (!String(err.errMsg || '').includes('cancel')) notify('选择媒体失败') }
  const onSuccess = result => { const files = result.tempFiles || (result.tempFilePaths || []).map(tempFilePath => ({ tempFilePath })); if (isVideo) postDraft.value.media = []; files.forEach(file => { if (postDraft.value.media.length < 9) postDraft.value.media.push({ url: file.tempFilePath, type }) }) }
  if (uni.chooseMedia) uni.chooseMedia({ count: isVideo ? 1 : Math.max(1, 9 - postDraft.value.media.length), mediaType: [type], sourceType: ['album', 'camera'], success: onSuccess, fail: onFail })
  else if (isVideo) uni.chooseVideo({ sourceType: ['album', 'camera'], success: r => onSuccess({ tempFilePaths: [r.tempFilePath] }), fail: onFail })
  else uni.chooseImage({ count: Math.max(1, 9 - postDraft.value.media.length), sourceType: ['album', 'camera'], success: onSuccess, fail: onFail })
}
function removeMedia(index) { postDraft.value.media.splice(index, 1) }
function saveLocalFile(path) { return new Promise(resolve => { if (!uni.saveFile) return resolve(path); uni.saveFile({ tempFilePath: path, success: r => resolve(r.savedFilePath || path), fail: () => resolve(path) }) }) }
async function publish() {
  if (!postDraft.value.petIds.length) return error.value = '请选择至少一只宠物'
  if (!postDraft.value.date) return error.value = '请选择日期'
  if (!postDraft.value.media.length && !postDraft.value.text.trim()) return error.value = '请添加照片、视频或一段文字'
  busy.value = true; error.value = ''
  try {
    const media = []
    for (const item of postDraft.value.media) media.push({ type: item.type, url: cloudAvailable && cloudToken() ? await uploadMedia(item.url, item.type) : await saveLocalFile(item.url) })
    const newPost = { id: uid(), petIds: [...postDraft.value.petIds], date: postDraft.value.date, text: postDraft.value.text.trim(), media, likes: 0, liked: false, comments: [], createdAt: new Date().toISOString() }
    journal.value.moments.unshift(newPost)
    commit(); sheet.value = ''; activeTab.value = 'timeline'; notify('记录发布成功')
    if (postDraft.value.public && cloudToken()) { try { await sharePost({ petNames: newPost.petIds.map(id => pets.value.find(p => p.id === id)?.name).filter(Boolean), date: newPost.date, text: newPost.text, media: newPost.media }); await loadSocial() } catch { notify('私人相册已保存，分享到宠友圈失败') } }
  } catch (e) { error.value = e.message || '发布失败' } finally { busy.value = false }
}
function savePet() { if (!petDraft.value.name?.trim()) return error.value = '请填写宠物名字'; const entry = { ...petDraft.value, id: petDraft.value.id || uid(), name: petDraft.value.name.trim() }; const index = pets.value.findIndex(p => p.id === entry.id); if (index < 0) journal.value.pets.push(entry); else journal.value.pets[index] = entry; selectedPetId.value = entry.id; commit(); closeSheet() }
function addPet() { petDraft.value = { name: '', species: '狗狗', breed: '', birthday: today(), avatar: '' }; sheet.value = 'pet'; error.value = '' }
function selectPet(id) { selectedPetId.value = id; activeTab.value = 'timeline' }
function togglePostPet(id) { const ids = postDraft.value.petIds; const index = ids.indexOf(id); if (index < 0) ids.push(id); else ids.splice(index, 1) }
function openDetail(post) { selectedPost.value = post; activeTab.value = 'detail' }
function saveEvent() { if (!eventDraft.value.title.trim()) return error.value = '请填写事件名称'; journal.value.events.unshift({ ...eventDraft.value, id: uid() }); commit(); closeSheet() }
function toggleLike(post) { post.liked = !post.liked; post.likes = Math.max(0, (post.likes || 0) + (post.liked ? 1 : -1)); commit() }
function addComment(post) { if (!commentText.value.trim()) return; post.comments ||= []; post.comments.push({ id: uid(), text: commentText.value.trim() }); commentText.value = ''; commentFor.value = ''; commit() }
function preview(post, index) { const images = (post.media || []).filter(m => m.type === 'image').map(m => m.url); if (images.length) uni.previewImage({ urls: images, current: (post.media || [])[index]?.url }) }
function removePost(post) { uni.showModal({ title: '删除这条成长记录？', content: '删除后无法恢复', success: r => { if (r.confirm) { journal.value.moments = journal.value.moments.filter(p => p.id !== post.id); selectedPost.value = null; activeTab.value = 'timeline'; commit() } } }) }
async function authenticate() { if (!authDraft.value.email || !authDraft.value.password) return error.value = '请输入邮箱和密码'; busy.value = true; error.value = ''; try { await login(authDraft.value.email, authDraft.value.password, authDraft.value.mode); const remote = await pullJournal(); if (remote?.pets) { journal.value = remote; saveJournal(remote) } else await pushJournal(journal.value); sheet.value = ''; await loadSocial(); notify('同步已开启') } catch (e) { error.value = e.message } finally { busy.value = false } }
async function loadSocial() { if (!cloudAvailable || !cloudToken()) return; try { socialPosts.value = await socialFeed() } catch { notify('宠友圈加载失败') } }
async function toggleSocial(post) { try { const result = await likeSocial(post.id); post.liked = result.liked; post.likes += result.liked ? 1 : -1 } catch { notify('点赞失败') } }
async function sendSocialComment(post) { const value = commentText.value.trim(); if (!value) return; try { const result = await commentSocial(post.id, value); post.comments.push({ id: result.id, author: '我', text: value }); commentText.value = ''; commentFor.value = '' } catch { notify('评论失败') } }
function switchSocial(value) { socialMode.value = value; if (value) { if (!cloudAvailable || !cloudToken()) { sheet.value = 'account'; return } loadSocial() } }
async function refreshCloud() { if (!cloudAvailable || !cloudToken()) return; try { const remote = await pullJournal(); if (remote?.pets) { journal.value = remote; saveJournal(remote) } } catch { notify('同步失败，已显示本机记录') } }
function logout() { setCloudToken(''); closeSheet(); notify('已退出同步账号') }
onMounted(refreshCloud)
</script>

<template>
  <view class="app-shell">
    <view class="topbar"><view class="wordmark"><text class="brand-dot">✿</text> 麦麦 <text class="brand-sub">PAW MEMORIES</text></view><view class="top-action" @click="sheet = 'account'">{{ cloudToken() ? '☁' : '☰' }}</view></view>
    <view class="page-content">
      <view v-if="activeTab === 'profile'">
      <view class="pet-banner" @click="openPet(pet)">
        <view class="banner-glow"></view>
        <view class="pet-illustration"><view class="ear ear-left"></view><view class="ear ear-right"></view><view class="pet-face"><view class="pet-eye left"></view><view class="pet-eye right"></view><view class="pet-nose"></view><view class="pet-mouth"></view><view class="blush blush-left"></view><view class="blush blush-right"></view></view><view class="pet-body"></view><view class="pet-collar"></view></view>
        <view class="banner-copy"><view class="eyebrow">我的毛孩子 <text>✦</text></view><view class="pet-title">{{ pet.name }} <text>↗</text></view><view class="pet-meta">{{ pet.breed || pet.species }} · {{ age }}</view><view class="birthday-pill">🎂 {{ formatDate(pet.birthday) }} 出生</view></view>
        <view class="banner-doodle">✳</view>
      </view>
      <view class="stats-row"><view><text class="stat-number">{{ posts.length }}</text><text class="stat-label">成长瞬间</text></view><view class="stat-divider"></view><view><text class="stat-number">{{ countPhotos }}</text><text class="stat-label">珍藏照片</text></view><view class="stat-divider"></view><view><text class="stat-number">{{ events.length }}</text><text class="stat-label">健康记录</text></view></view>
      <view class="profile-list-title">我的宠物 <text @click="addPet">＋ 添加宠物</text></view>
      <view v-for="animal in pets" :key="animal.id" class="profile-pet" @click="selectPet(animal.id)"><view class="profile-avatar">{{ animal.species === '猫咪' ? '🐱' : '🐶' }}</view><view class="profile-pet-copy"><view>{{ animal.name }} <text>›</text></view><text>{{ animal.breed || animal.species }} · {{ formatDate(animal.birthday) }} 出生</text></view><view class="profile-edit" @click.stop="openPet(animal)">编辑</view></view>
      <view class="profile-list-title">健康备忘 <text @click="activeTab = 'health'">查看全部 ›</text></view><view class="profile-health"><view @click="activeTab = 'health'"><text>✚</text><view>疫苗事件</view></view><view @click="activeTab = 'health'"><text>✿</text><view>上次驱虫</view><small>{{ latestDeworm ? formatDate(latestDeworm.date) : '待记录' }}</small></view></view>
      </view>
      <view v-else-if="activeTab === 'timeline'">
        <view class="section-heading"><view><text class="section-kicker">OUR LITTLE STORY</text><view class="section-title">成长时间线 <text>✿</text></view></view><view class="year-label">每一刻都珍贵</view></view><view class="feed-switch"><view :class="{ active: !socialMode }" @click="switchSocial(false)">我的相册</view><view :class="{ active: socialMode }" @click="switchSocial(true)">宠友圈</view></view><view v-if="!socialMode">
        <scroll-view scroll-x class="pet-filters"><view class="filter-inner"><view :class="['pet-chip', { active: selectedPetId === 'all' }]" @click="selectedPetId = 'all'">全部故事</view><view v-for="animal in pets" :key="animal.id" :class="['pet-chip', { active: selectedPetId === animal.id }]" @click="selectedPetId = animal.id">{{ animal.species === '猫咪' ? '🐱' : '🐶' }} {{ animal.name }}</view></view></scroll-view>
        <view class="composer" @click="openPost"><view class="composer-icon">＋</view><view><view class="composer-title">记录今天的小幸福</view><view class="composer-hint">照片、视频，还有想说的话...</view></view><text class="composer-arrow">›</text></view>
        <view v-if="!posts.length" class="empty-state"><view class="empty-emoji">🐾</view><view>第一条成长记录，等你来写</view></view>
        <view v-for="post in posts" :key="post.id" class="moment-row"><view class="timeline-date"><text class="date-day">{{ monthDay(post.date).day }}</text><text class="date-month">{{ monthDay(post.date).month }}</text><view class="timeline-dot"></view></view><view class="moment-card" @click="openDetail(post)"><view class="moment-head"><view class="mini-avatar">🐾</view><view><view class="moment-name">{{ petName(post) }}</view><view class="moment-time">{{ formatDate(post.date) }}</view></view><view class="more" @click.stop="removePost(post)">···</view></view><view v-if="post.text" class="moment-text">{{ post.text }}</view><view v-if="post.media?.length" :class="['media-grid', { single: post.media.length === 1, double: post.media.length === 2 }]" ><view v-for="(item,index) in post.media" :key="index" class="media-tile"><image v-if="item.type === 'image'" :src="item.url" mode="aspectFill" @click.stop="preview(post,index)"/><video v-else :src="item.url" controls object-fit="cover"/></view></view><view v-else class="text-only-art">✿ <text>今天也是被爱包围的一天</text></view><view class="moment-actions"><view @click.stop="toggleLike(post)"><text :class="['action-heart', { liked: post.liked }]">{{ post.liked ? '♥' : '♡' }}</text> {{ post.likes || '喜欢' }}</view><view @click.stop="commentFor = commentFor === post.id ? '' : post.id">♧ 评论</view><view class="paw-mark">🐾</view></view><view v-if="post.comments?.length" class="comments"><view v-for="c in post.comments" :key="c.id"><text>我：</text>{{ c.text }}</view></view><view v-if="commentFor === post.id" class="comment-box"><input v-model="commentText" placeholder="写下你的评论..." confirm-type="send" @confirm="addComment(post)"/><text @click.stop="addComment(post)">发送</text></view></view></view>
        <view class="end-note">✿ · 我们的故事，未完待续 · ✿</view></view>
        <view v-else class="social-feed"><view v-if="!socialPosts.length" class="empty-state">宠友圈还没有动态，分享第一条吧 🐾</view><view v-for="post in socialPosts" :key="post.id" class="social-card"><view class="moment-head"><view class="mini-avatar">🐾</view><view><view class="moment-name">{{ post.petNames.join('、') }}</view><view class="moment-time">{{ post.author }} · {{ formatDate(post.date) }}</view></view></view><view v-if="post.text" class="moment-text">{{ post.text }}</view><view v-if="post.media.length" :class="['media-grid', { single: post.media.length === 1, double: post.media.length === 2 }]"><view v-for="(item,index) in post.media" :key="index" class="media-tile"><image v-if="item.type === 'image'" :src="item.url" mode="aspectFill" @click="preview(post,index)"/><video v-else :src="item.url" controls/></view></view><view class="moment-actions"><view @click="toggleSocial(post)"><text :class="['action-heart', { liked: post.liked }]">{{ post.liked ? '♥' : '♡' }}</text> {{ post.likes || '喜欢' }}</view><view @click="commentFor = commentFor === post.id ? '' : post.id">♧ 评论</view></view><view v-if="post.comments.length" class="comments"><view v-for="c in post.comments" :key="c.id"><text>{{ c.author }}：</text>{{ c.text }}</view></view><view v-if="commentFor === post.id" class="comment-box"><input v-model="commentText" placeholder="写下你的评论..."/><text @click="sendSocialComment(post)">发送</text></view></view></view>
      </view>
      <view v-else-if="activeTab === 'detail' && selectedPost" class="detail-view"><view class="detail-back" @click="activeTab = 'timeline'">‹ 返回时间线</view><view class="detail-media" v-if="selectedPost.media?.length"><view v-for="(item,index) in selectedPost.media" :key="index"><image v-if="item.type === 'image'" :src="item.url" mode="aspectFill" @click="preview(selectedPost,index)"/><video v-else :src="item.url" controls/></view></view><view v-else class="detail-placeholder">✿<text>一个珍贵的成长瞬间</text></view><view class="detail-date">{{ formatDate(selectedPost.date) }}</view><view class="detail-text">{{ selectedPost.text || '这一天，留下了美好的回忆。' }}</view><view class="detail-label">出镜的毛孩子</view><view class="detail-pets"><view v-for="id in selectedPost.petIds" :key="id" @click="selectPet(id)"><view class="detail-pet-avatar">{{ pets.find(p => p.id === id)?.species === '猫咪' ? '🐱' : '🐶' }}</view><text>{{ pets.find(p => p.id === id)?.name }}</text></view></view><view class="detail-label">互动</view><view class="detail-actions"><view @click="toggleLike(selectedPost)">{{ selectedPost.liked ? '♥' : '♡' }} {{ selectedPost.likes || 0 }} 个喜欢</view><view @click="commentFor = selectedPost.id">♧ 评论</view></view><view v-for="c in selectedPost.comments" :key="c.id" class="detail-comment">我：{{ c.text }}</view><view v-if="commentFor === selectedPost.id" class="comment-box"><input v-model="commentText" placeholder="写下你的评论..."/><text @click="addComment(selectedPost)">发送</text></view></view>
      <view v-else class="health-view"><view class="section-heading"><view><text class="section-kicker">LITTLE HEALTH BOOK</text><view class="section-title">健康小手账 <text>✿</text></view></view></view><view class="health-summary"><view class="health-tile vaccine" @click="openEvent('vaccine')"><text class="health-icon">✚</text><view class="health-name">疫苗记录</view><view class="health-date">{{ nextVaccine ? '下次 ' + formatDate(nextVaccine.date) : '点击添加记录' }}</view></view><view class="health-tile deworm" @click="openEvent('deworm')"><text class="health-icon">✿</text><view class="health-name">上次驱虫</view><view class="health-date">{{ latestDeworm ? formatDate(latestDeworm.date) : '点击添加记录' }}</view></view></view><view class="section-title small">全部记录</view><view v-if="!events.length" class="empty-state">还没有健康记录</view><view v-for="event in events" :key="event.id" class="event-row"><view :class="['event-icon', event.type]">{{ event.type === 'vaccine' ? '✚' : '✿' }}</view><view class="event-info"><view>{{ event.title }}</view><text>{{ event.note || (event.type === 'vaccine' ? '疫苗' : '驱虫') }}</text></view><view class="event-date">{{ formatDate(event.date) }}</view></view><button class="add-event" @click="openEvent('vaccine')">＋ 添加健康记录</button></view>
    </view>
    <view class="bottom-nav"><view :class="{ selected: activeTab === 'profile' }" @click="activeTab = 'profile'"><text>◉</text><text>我的宠物</text></view><view :class="{ selected: activeTab === 'timeline' || activeTab === 'detail' }" @click="activeTab = 'timeline'"><text>▦</text><text>成长相册</text></view><view class="nav-add" @click="openPost">＋</view></view>
    <view v-if="sheet" class="overlay" @click="closeSheet"><view class="sheet" @click.stop><view class="sheet-handle"></view><view class="sheet-header"><text>{{ sheet === 'post' ? '记录一个新瞬间' : sheet === 'pet' ? '编辑宠物资料' : sheet === 'event' ? '添加健康记录' : '云端同步' }}</text><text @click="closeSheet">×</text></view>
      <view v-if="sheet === 'post'"><view class="field-label">出镜的毛孩子</view><view class="post-pets"><view v-for="animal in pets" :key="animal.id" :class="{ active: postDraft.petIds.includes(animal.id) }" @click="togglePostPet(animal.id)">{{ animal.species === '猫咪' ? '🐱' : '🐶' }} {{ animal.name }}</view></view><view class="field-label">照片或视频 <text>最多 9 张照片 / 1 段视频</text></view><view class="draft-media"><view v-for="(item,index) in postDraft.media" :key="index" class="draft-tile"><image v-if="item.type === 'image'" :src="item.url" mode="aspectFill"/><video v-else :src="item.url"/><text @click="removeMedia(index)">×</text></view><view v-if="postDraft.media.length < 9 && postDraft.media[0]?.type !== 'video'" class="draft-add" @click="chooseMedia('image')">＋<text>照片</text></view><view v-if="!postDraft.media.length" class="draft-add" @click="chooseMedia('video')">▷<text>视频</text></view></view><view v-if="cloudAvailable && cloudToken()" class="share-toggle" @click="postDraft.public = !postDraft.public"><text>{{ postDraft.public ? '☑' : '□' }}</text> 同时分享到宠友圈</view><view class="field-label">这一天</view><picker mode="date" :value="postDraft.date" @change="postDraft.date = $event.detail.value"><view class="input-like">{{ formatDate(postDraft.date) }} <text>⌄</text></view></picker><view class="field-label">说点什么 <text>可选</text></view><textarea v-model="postDraft.text" class="text-area" placeholder="记录它的第一次、一个可爱的瞬间..." maxlength="500"/></view>
      <view v-else-if="sheet === 'pet'"><view class="field-label">名字</view><input v-model="petDraft.name" class="form-input" placeholder="宠物的名字"/><view class="field-label">品种</view><input v-model="petDraft.breed" class="form-input" placeholder="例如：柯基"/><view class="field-label">生日</view><picker mode="date" :value="petDraft.birthday" @change="petDraft.birthday = $event.detail.value"><view class="input-like">{{ formatDate(petDraft.birthday) }} <text>⌄</text></view></picker></view>
      <view v-else-if="sheet === 'event'"><view class="field-label">记录类型</view><view class="segmented"><view :class="{ active: eventDraft.type === 'vaccine' }" @click="eventDraft.type = 'vaccine'">疫苗</view><view :class="{ active: eventDraft.type === 'deworm' }" @click="eventDraft.type = 'deworm'">驱虫</view></view><view class="field-label">事件名称</view><input v-model="eventDraft.title" class="form-input" placeholder="例如：狂犬疫苗"/><view class="field-label">日期</view><picker mode="date" :value="eventDraft.date" @change="eventDraft.date = $event.detail.value"><view class="input-like">{{ formatDate(eventDraft.date) }} <text>⌄</text></view></picker><view class="field-label">备注 <text>可选</text></view><input v-model="eventDraft.note" class="form-input" placeholder="补充说明"/></view>
      <view v-else class="account-form"><view v-if="!cloudAvailable" class="account-note">配置服务器地址后，可用同一账号在小程序和 App 中同步所有成长记录。当前记录保存在本机。</view><template v-else-if="!cloudToken()"><view class="segmented"><view :class="{ active: authDraft.mode === 'login' }" @click="authDraft.mode = 'login'">登录</view><view :class="{ active: authDraft.mode === 'register' }" @click="authDraft.mode = 'register'">注册</view></view><view class="field-label">邮箱</view><input v-model="authDraft.email" class="form-input" type="text" placeholder="your@email.com"/><view class="field-label">密码</view><input v-model="authDraft.password" class="form-input" password placeholder="至少 8 位"/></template><view v-else class="account-note">已登录云端账号。成长记录会在发布后同步，也可手动刷新。</view></view>
      <view v-if="error" class="form-error">{{ error }}</view><button v-if="sheet === 'post'" class="primary-button" :disabled="busy" @click="publish">{{ busy ? '正在发布...' : '发布成长记录' }}</button><button v-else-if="sheet === 'pet'" class="primary-button" @click="savePet">保存资料</button><button v-else-if="sheet === 'event'" class="primary-button" @click="saveEvent">保存记录</button><button v-else-if="cloudAvailable && !cloudToken()" class="primary-button" :disabled="busy" @click="authenticate">{{ busy ? '请稍候...' : authDraft.mode === 'register' ? '注册并开启同步' : '登录并同步' }}</button><button v-else-if="cloudToken()" class="primary-button" @click="refreshCloud(); closeSheet()">从云端刷新</button><view v-if="sheet === 'account' && cloudToken()" class="logout" @click="logout">退出账号</view>
    </view></view>
  </view>
</template>

